import {expect,test} from 'bun:test'
import {buildM75Dependencies,deriveM75Reconciliation,deriveM75RosterFindings,m75CanonicalJson,validateM75Save} from '../../packages/neuvetra-database/src/m75-validation'
import {M75_LIMITATIONS} from '../../packages/neuvetra-database/src/m75-contract'
import {classificationCases,independentGraph,qaHash,qaId,type IndependentGraph} from './m75-independent-scenarios'

const hash=(value:unknown)=>qaHash(m75CanonicalJson(value))
const coverage=(g:IndependentGraph)=>g.coverage.versions.find((v:any)=>v.id===g.coverage.headVersionId)
const currentHeads=(g:IndependentGraph)=>g.mobile.worksheets.map((w:any)=>w.versions.find((v:any)=>v.id===w.headVersionId))
function capture(g:IndependentGraph){g.version.dependencies=buildM75Dependencies(coverage(g),currentHeads(g),hash);for(const r of g.reviews)r.dependencies=structuredClone(g.version.dependencies)}
function derive(g:IndependentGraph){g.version.findings=deriveM75RosterFindings(g.version.activity,coverage(g));return deriveM75Reconciliation(g.companyId,coverage(g),currentHeads(g),g.version,g.reviews,hash)}
function unchangedFlags(r:any){expect(r.synthetic).toBe(true);expect(r.scope1Completeness).toBe('incomplete');expect(r.corporateCompleteness).toBe('incomplete');expect(r.releaseEligible).toBe(false);expect(r.assurance).toBe('none');expect(r.emissionsTotals).toBeNull();expect(r.limitations).toEqual([...M75_LIMITATIONS]);for(const forbidden of ['fleetTotal','totalEmissions','netEmissions','grossEmissions'])expect(r).not.toHaveProperty(forbidden)}

for(const c of classificationCases)test(`M75 independent ${c.id} [${c.requirement}]`,()=>{
 const g=independentGraph();capture(g);c.mutate(g);if(c.refreshDependencies)capture(g);const r=derive(g)
 expect(r.status,JSON.stringify(r.findings)).toBe(c.expectedStatus);unchangedFlags(r)
 if(c.minimumRows!==undefined)expect(r.rows.length).toBeGreaterThanOrEqual(c.minimumRows)
 if(c.row!==undefined){const row=r.rows.find(x=>x.rosterRowId===qaId(200+c.row!));expect(row).toBeDefined();expect(row!.status,JSON.stringify(row!.findings)).toBe(c.expectedRowStatus)}
 if(c.expectedStatus==='reconciled_bounded_synthetic'){expect(r.counts.blockingFindings).toBe(0);expect(r.rows.every(x=>x.status==='matched_reviewed')).toBe(true)}
 else expect(r.findings.some(x=>x.blocking)).toBe(true)
})

test('M75 independent does not erase a fourth vehicle when the M74 capacity is full',()=>{
 const g=independentGraph(),s=g.version.activity.rosterStatement
 for(let i=2;i<4;i++){const a=structuredClone(s.assets[0]);a.rowId=qaId(200+i);a.assetId=`QA-FLEET-${i}`;s.assets.push(a);g.version.activity.links.push({rowId:a.rowId,sourceId:qaId(100+i)});const source=structuredClone(coverage(g).snapshot.sources.find((x:any)=>x.domain==='mobile_combustion'));source.id=qaId(100+i);coverage(g).snapshot.sources.push(source)}
 const third=structuredClone(g.mobile.worksheets[0]);third.worksheetId=qaId(322);third.sourceId=qaId(102);third.vehicleAssetId='QA-FLEET-2';third.headVersionId=qaId(302);third.versions[0].id=qaId(302);third.versions[0].worksheetId=third.worksheetId;third.versions[0].activity.vehicle.assetId=third.vehicleAssetId;third.versions[0].activity.binding.sourceId=third.sourceId;third.versions[0].review.versionId=qaId(302);g.mobile.worksheets.push(third);capture(g)
 const r=derive(g),row=r.rows.find(x=>x.rosterRowId===qaId(203));expect(r.status).toBe('blocked');expect(r.counts.evidenceRows).toBe(4);expect(r.counts.currentWorkpaperStreams).toBe(3);expect(row?.status).toBe('capacity_blocked');unchangedFlags(r)
})

test('M75 independent known classification contradictions cannot be hidden by matching source and asset IDs',()=>{
 for(const [field,value] of Object.entries({modelYear:2019,vehicleClass:'Medium- and Heavy-Duty Vehicles',fuel:'Fossil Diesel',controlBasis:'owned_operational_control_full_year'})){
  const g=independentGraph();if(field==='modelYear')g.version.activity.rosterStatement.assets[0][field]=value;else {const v=g.mobile.worksheets[0].versions[0];v.activity.vehicle[field]=field==='vehicleClass'?'Light-Duty Trucks':field==='fuel'?'B20':'other_control_arrangement'}capture(g)
  const r=derive(g),row=r.rows.find(x=>x.rosterRowId===qaId(200));expect(r.status).toBe('blocked');expect(row?.status).not.toBe('matched_reviewed');expect(row?.findings.some(x=>x.blocking)).toBe(true)
 }
})

test('M75 independent save admission normalizes declared collisions but does not remove rows',()=>{
 const g=independentGraph();capture(g);const input={...g.version.activity,expectedDependencySha256:g.version.dependencies.dependencySha256,expectedVersionId:null,expectedVersionSha256:null,correctionReason:null,idempotencyKey:qaId(900)}
 input.rosterStatement.assets[0].assetId=' case-a ';input.rosterStatement.assets[1].assetId='CASE-A';input.rosterStatement.assets[1].aliases=[' Z-ALIAS ','a-alias']
 const normalized=validateM75Save(input);expect(normalized.rosterStatement!.assets).toHaveLength(2);expect(normalized.rosterStatement!.assets.map(x=>x.assetId)).toEqual(['CASE-A','CASE-A']);expect(normalized.rosterStatement!.assets[1]!.aliases).toEqual(['A-ALIAS','Z-ALIAS'])
 expect(deriveM75RosterFindings(normalized,coverage(g)).filter(x=>x.code==='duplicate_asset_identity')).toHaveLength(2)
})

test('M75 independent save admission rejects impossible calendar dates and numeric/coerced identifiers',()=>{
 for(const patch of [{period:{start:'2025-02-30',endExclusive:'2026-01-01'}},{period:{start:'2025-13-01',endExclusive:'2026-01-01'}},{assetId:123},{modelYear:2022.5}]){
  const g=independentGraph();capture(g);Object.assign(g.version.activity.rosterStatement.assets[0],patch);const input={...g.version.activity,expectedDependencySha256:g.version.dependencies.dependencySha256,expectedVersionId:null,expectedVersionSha256:null,correctionReason:null,idempotencyKey:qaId(900)}
  expect(()=>validateM75Save(input),JSON.stringify(patch)).toThrow()
 }
})

test('M75 independent classification rejects supplied current incomplete head (actual selection pending native review)',()=>{
 const g=independentGraph(),w=g.mobile.worksheets[0],next=structuredClone(w.versions[0]);next.id=qaId(950);next.version=2;next.versionSha256=qaHash('new-unreviewed-head');next.previousVersionId=w.headVersionId;next.review=null;next.calculation=null;next.activity.distanceMiles=null;next.activityStatus.mileage='missing';w.versions.push(next);w.headVersionId=next.id;capture(g)
 const r=derive(g),row=r.rows.find(x=>x.rosterRowId===qaId(200));expect(r.status).toBe('blocked');expect(row?.status).toBe('workpaper_incomplete');expect(r.workpaperPins.find(x=>x.worksheetId===w.worksheetId)?.version.id).toBe(next.id)
})

import {expect,test} from 'bun:test'
import {decodeFleetVersion,fleetReportSnapshotDownload,fleetReportDownload,fleetReportRequest} from '../../apps/site-web/src/lib/m75-api'
import {buildM75Dependencies,deriveM75RosterFindings,deriveM75Reconciliation,m75CanonicalJson,m75StatementText,m75InputPayload,m75ContentPayload,m75VersionHashPayload,m75ReportHashPayload} from '../../packages/neuvetra-database/src/m75-validation'
import {m75RenderReport,m75ReportSnapshot} from '../../packages/neuvetra-database/src/m75-report'
import {independentGraph,qaHash,qaId} from './m75-independent-scenarios'
import {m71VersionHashPayload} from '../../packages/neuvetra-database/src/m71-validation'
import {decodeCorporateVersion} from '../../apps/site-web/src/lib/m71-api'
const hash=(v:unknown)=>qaHash(m75CanonicalJson(v))

/** Uses exact retained synthetic M71/M74 bytes that pass their real browser
 * decoders. The M75 report is a reviewer-built attack fixture, not a saved record. */
async function reportFixture(){
 const proof=await Bun.file(new URL('./m75-independent-native-proof.json',import.meta.url)).json()
 proof.boundCoverageVersion=structuredClone(proof.coverageVersion)
 const g=independentGraph(),cv=proof.coverageVersion,heads=proof.workpaperVersions,v=g.version
 g.companyId=cv.companyId;v.companyId=cv.companyId;v.createdAt='2026-09-16T06:00:00.000Z'
 v.activity.coverageVersionId=cv.id;v.activity.coverageVersionSha256=cv.versionSha256
 const first=v.activity.rosterStatement.assets[0],mobile=heads[0]
 Object.assign(first,{assetId:mobile.activity.vehicle.assetId,entityId:mobile.activity.binding.entityId,facilityId:mobile.activity.binding.facilityId})
 v.activity.rosterStatement.assets=[first];v.activity.rosterStatement.coveredEntityIds=cv.snapshot.entities.map((x:any)=>x.id)
 v.activity.links=[{rowId:first.rowId,sourceId:mobile.activity.binding.sourceId}]
 v.contributorIds=[...new Set([v.createdBy,...cv.contributorIds,...heads.flatMap((x:any)=>x.contributorIds)])].sort()
 v.activity.rosterStatement.assets[0].modelYear=2024
 v.dependencies=buildM75Dependencies(cv,heads,hash);v.statement.input=v.activity.rosterStatement;v.statement.text=m75StatementText(v.activity,cv);v.statement.byteLength=new TextEncoder().encode(v.statement.text).length;v.statement.sha256=qaHash(v.statement.text);v.findings=deriveM75RosterFindings(v.activity,cv);v.inputSha256=hash(m75InputPayload(v));v.contentSha256=hash(m75ContentPayload(v));v.versionSha256=hash(m75VersionHashPayload(v));await decodeFleetVersion(v,g.companyId)
 const result=deriveM75Reconciliation(g.companyId,cv,heads,v,[],hash)
 expect(result.status).toBe('blocked');expect(result.rows.some(x=>x.status==='unsupported')).toBe(true)
 return {g,proof,snapshot:m75ReportSnapshot(v,null,result)}
}
function metadata(g:any,snapshot:any){
 const snapshotJson=m75CanonicalJson(snapshot),html=m75RenderReport(snapshot),r:any={id:qaId(980),companyId:g.companyId,rosterId:g.version.rosterId,rosterVersionId:g.version.id,createdBy:qaId(2),createdAt:'2026-09-16T06:01:00.000Z',rendererVersion:'m75-fleet-reconciliation-report-v1',snapshotJson,html,snapshotSha256:qaHash(snapshotJson),htmlSha256:qaHash(html),htmlByteLength:new TextEncoder().encode(html).length,reportSha256:''};r.reportSha256=hash(m75ReportHashPayload(r));const {snapshotJson:_,html:__,...meta}=r;return {meta,text:snapshotJson,html,report:r}
}

test('M75 independent historical snapshot decoder distinguishes hashes from semantic findings',async()=>{
 const {g,proof,snapshot}=await reportFixture(),originalFetch=globalThis.fetch,actor={accessToken:'synthetic-review-token',userId:qaId(2),role:'owner' as const}
 try {
  const original=metadata(g,snapshot);globalThis.fetch=(async(url:any)=>new Response(String(url).endsWith('/proof')?JSON.stringify({reportId:original.meta.id,proof}):original.text,{status:200})) as typeof fetch
  expect(await fleetReportSnapshotDownload(actor,g.companyId,original.meta)).toBe(original.text)
  const forged=structuredClone(snapshot);forged.reconciliation.status='reconciled_bounded_synthetic';forged.reconciliation.findings=[];forged.reconciliation.rows=forged.reconciliation.rows.map(x=>({...x,status:'matched_reviewed' as const,findings:[]}));forged.reconciliation.counts.blockingFindings=0;forged.reconciliation.counts.reconciledRows=forged.reconciliation.rows.length;const {contentSha256:_,...body}=forged.reconciliation;forged.reconciliation.contentSha256=hash(body)
  const altered=metadata(g,forged);globalThis.fetch=(async(url:any)=>new Response(String(url).endsWith('/proof')?JSON.stringify({reportId:altered.meta.id,proof}):altered.text,{status:200})) as typeof fetch
  await expect(fleetReportSnapshotDownload(actor,g.companyId,altered.meta)).rejects.toThrow()
 } finally {globalThis.fetch=originalFetch}
})

for(const mutation of ['wrong_report_id','omitted_mobile_proof','duplicate_mobile_proof','missing_coverage','altered_mobile_calculation','missing_bound_coverage','wrong_bound_coverage'] as const){
 test(`M75 independent report proof rejects ${mutation}`,async()=>{
  const {g,proof,snapshot}=await reportFixture(),record=metadata(g,snapshot),originalFetch=globalThis.fetch
  const envelope:any={reportId:record.meta.id,proof:structuredClone(proof)}
  if(mutation==='wrong_report_id')envelope.reportId=qaId(981)
  if(mutation==='omitted_mobile_proof')envelope.proof.workpaperVersions=[]
  if(mutation==='duplicate_mobile_proof')envelope.proof.workpaperVersions.push(structuredClone(proof.workpaperVersions[0]))
  if(mutation==='missing_coverage')envelope.proof.coverageVersion=null
  if(mutation==='altered_mobile_calculation')envelope.proof.workpaperVersions[0].calculation.total.unrounded='0'
  if(mutation==='missing_bound_coverage')envelope.proof.boundCoverageVersion=null
  if(mutation==='wrong_bound_coverage')envelope.proof.boundCoverageVersion.id=qaId(967)
  try{globalThis.fetch=(async(url:any)=>new Response(String(url).endsWith('/proof')?JSON.stringify(envelope):record.text)) as typeof fetch
   await expect(fleetReportSnapshotDownload({accessToken:'synthetic',userId:qaId(2),role:'owner'},g.companyId,record.meta)).rejects.toThrow()
  }finally{globalThis.fetch=originalFetch}
 })
}

test('M75 real report POST and HTML download both demand matching historical proof',async()=>{
 const {g,proof,snapshot}=await reportFixture(),record=metadata(g,snapshot),originalFetch=globalThis.fetch,actor={accessToken:'synthetic',userId:qaId(2),role:'owner' as const},calls:string[]=[]
 try{
  globalThis.fetch=(async(url:any,options:any)=>{calls.push(String(url));return new Response(String(url).endsWith('/proof')?JSON.stringify({reportId:record.meta.id,proof}):String(url).endsWith('/download')?record.html:options?.method==='POST'?JSON.stringify(record.report):record.text)}) as typeof fetch
  expect(await fleetReportDownload(actor,g.companyId,record.meta)).toBe(record.html)
  expect(calls.filter(x=>x.endsWith('/proof')).length).toBe(1)
  expect(await fleetReportRequest(actor,g.companyId,g.version.rosterId,{expectedReconciliationSha256:snapshot.reconciliation.contentSha256,idempotencyKey:qaId(982)})).toEqual(record.report)
  expect(calls.filter(x=>x.endsWith('/proof')).length).toBe(2)
 }finally{globalThis.fetch=originalFetch}
})

test('M75 download abort while old actor response is pending cannot return report bytes',async()=>{
 const {g,snapshot}=await reportFixture(),record=metadata(g,snapshot),originalFetch=globalThis.fetch,controller=new AbortController();let release!:(r:Response)=>void,calls=0
 try{
  globalThis.fetch=(()=>{calls++;return new Promise<Response>(resolve=>{release=resolve})}) as typeof fetch
  const pending=fleetReportSnapshotDownload({accessToken:'synthetic',userId:qaId(2),role:'owner',signal:controller.signal},g.companyId,record.meta)
  controller.abort();release(new Response(record.text));await expect(pending).rejects.toThrow();expect(calls).toBe(1)
 }finally{globalThis.fetch=originalFetch}
})

test('M75 unauthorized report response invalidates actor exactly once and starts no proof fetch',async()=>{
 const {g,snapshot}=await reportFixture(),record=metadata(g,snapshot),originalFetch=globalThis.fetch;let calls=0,invalidations=0
 try{
  globalThis.fetch=(async()=>{calls++;return new Response('',{status:403})}) as typeof fetch
  await expect(fleetReportSnapshotDownload({accessToken:'synthetic',userId:qaId(2),role:'owner',onUnauthorized:()=>{invalidations++}},g.companyId,record.meta)).rejects.toThrow('access changed')
  expect(calls).toBe(1);expect(invalidations).toBe(1)
 }finally{globalThis.fetch=originalFetch}
})

test('M75 stale roster report must still independently validate bound roster findings',async()=>{
 const {g,proof,snapshot}=await reportFixture(),originalFetch=globalThis.fetch
 const successor=structuredClone(proof.coverageVersion);successor.previousVersionId=successor.id;successor.previousVersionSha256=successor.versionSha256;successor.id=qaId(970);successor.version++;successor.createdAt='2026-09-16T06:00:30.000Z';successor.correctionReason='Synthetic later boundary correction';successor.review=null;successor.versionSha256=hash(m71VersionHashPayload(successor));await decodeCorporateVersion(successor,g.companyId)
 const laterProof={...proof,coverageVersion:successor},stale=structuredClone(snapshot)
 stale.reconciliation=deriveM75Reconciliation(g.companyId,successor,proof.workpaperVersions,stale.version,[],hash)
 expect(stale.reconciliation.status).toBe('blocked');expect(stale.reconciliation.rows.some(x=>x.status==='unsupported')).toBe(true)
 try{
  const original=metadata(g,stale);globalThis.fetch=(async(url:any)=>new Response(String(url).endsWith('/proof')?JSON.stringify({reportId:original.meta.id,proof:laterProof}):original.text)) as typeof fetch
  expect(await fleetReportSnapshotDownload({accessToken:'synthetic',userId:qaId(2),role:'owner'},g.companyId,original.meta)).toBe(original.text)
  const altered=structuredClone(stale);altered.version.findings=[];altered.version.contentSha256=hash(m75ContentPayload(altered.version));altered.version.versionSha256=hash(m75VersionHashPayload(altered.version));altered.reconciliation=deriveM75Reconciliation(g.companyId,successor,proof.workpaperVersions,altered.version,[],hash)
  expect(altered.reconciliation.rows.some(x=>x.status==='unsupported')).toBe(false)
  const forged=metadata(g,altered);globalThis.fetch=(async(url:any)=>new Response(String(url).endsWith('/proof')?JSON.stringify({reportId:forged.meta.id,proof:laterProof}):forged.text)) as typeof fetch
  await expect(fleetReportSnapshotDownload({accessToken:'synthetic',userId:qaId(2),role:'owner'},g.companyId,forged.meta)).rejects.toThrow()
 }finally{globalThis.fetch=originalFetch}
})

/** Native SQL adversarial probes; every function attempt is rolled back.
 * Uses author fixture only for setup, independent mutations/expectations. */
import {createPostgresConnection,HostedWorkspaceDatabase} from '../../packages/neuvetra-database/src/hosted'
import {populateM75RecoveryFixture} from '../../tools/staging/m75-backend-fixture'
import {createM74Authority} from '../../apps/site-api/src/calculation/m74-authority'
import {m75CanonicalJson,m75ContentPayload,m75InputPayload,m75VersionHashPayload,m75StatementText,m75ReportHashPayload,m75ReviewHashPayload,deriveM75RosterFindings} from '../../packages/neuvetra-database/src/m75-validation'
import {qaHash} from './m75-independent-scenarios'
import {m75RenderReport} from '../../packages/neuvetra-database/src/m75-report'
import {readMigrationManifest} from '../../packages/neuvetra-database/src/staging-migrations'
import {M75_LIMITATIONS} from '../../packages/neuvetra-database/src/m75-contract'
import type {WorkspaceSql} from '../../packages/neuvetra-database/src/workspace'
const template=process.env.M75_QA_TEMPLATE??'m74_ops_restore17_1789509920941'
if(template!=='m63_integration'&&!/^m7[45]_(ops|qa|author)_[a-z0-9_]+$/.test(template))throw Error('Only isolated synthetic template names are permitted')
const name='m75_qa_sql_'+Date.now(),connect=(db:string,user='m63_test_admin')=>createPostgresConnection(`postgres://${user}@127.0.0.1:55463/${db}`,{tls:false,maxConnections:1}),hash=(v:unknown)=>qaHash(m75CanonicalJson(v)),admin=connect('postgres'),sqlPath='packages/neuvetra-database/src/migrations/0018_controlled_fleet.sql',rawSql=await Bun.file(sqlPath).text(),sql=rawSql.replace(/\r\n/g,'\n'),sqlSha256=qaHash(sql)
const outcomes:{id:string;expectedAccepted:boolean;accepted:boolean;error:string|null;pass:boolean}[]=[];let op:ReturnType<typeof connect>|undefined
try{
 await admin.exec(`create database ${name} template ${template}`);op=connect(name)
 const manifest=await readMigrationManifest(),receipts=(await op.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
 if(!receipts.every((r,i)=>r.name===manifest[i]?.name&&r.sha256===manifest[i]?.sha256)||manifest.at(-1)?.sha256!==sqlSha256)throw Error('Exact migration receipt/candidate mismatch')
 await op.transaction(async tx=>{for(const m of manifest.slice(receipts.length)){await tx.exec(m.sql);await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[m.name,m.sha256])}})
 const seed=await populateM75RecoveryFixture(op,name,55463),read=connect(name,'neuvetra_runtime'),ref=(await op.query<{project_ref:string}>('select project_ref from neuvetra.staging_target')).rows[0]!.project_ref,db=new(HostedWorkspaceDatabase as any)(read,ref) as HostedWorkspaceDatabase,authority=createM74Authority()
 const register=(await db.findControlledFleet(seed.users.owner,seed.companyId,authority))!,report=(await db.findControlledFleetReport(seed.users.owner,seed.companyId,seed.rosterId,seed.reportId,authority))!;await read.close()
 const before=(await op.query<{n:number}>('select count(*)::integer n from neuvetra.controlled_fleet_versions')).rows[0]!.n
 async function probe(id:string,expectedAccepted:boolean,query:string,params:unknown[],setup?:(tx:WorkspaceSql)=>Promise<void>,actor=seed.users.owner){const connection=connect(name,'neuvetra_runtime'),rollback=Symbol('independent rollback');let accepted=false,error:string|null=null;try{await connection.transaction(async tx=>{await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[seed.users.owner]);if(setup)await setup(tx);await tx.query("select set_config('request.jwt.claim.sub',$1,true)",[actor]);await tx.query(query,params);accepted=true;throw rollback})}catch(e){if(e!==rollback)error=(e as Error).message}finally{await connection.close()}outcomes.push({id,expectedAccepted,accepted,error,pass:accepted===expectedAccepted});console.log(JSON.stringify(outcomes.at(-1)))}
 function save(mutate:(activity:any,version:any)=>void=()=>{}){const prior=register.versions.at(-1)!,v=structuredClone(prior);v.id=crypto.randomUUID();v.version++;v.previousVersionId=prior.id;v.previousVersionSha256=prior.versionSha256;v.createdAt=new Date().toISOString();v.correctionReason='Independent SQL correction';v.activity.rosterStatement!.reference+='-SQL';mutate(v.activity,v);const statementId=crypto.randomUUID(),text=m75StatementText(v.activity,register.proof.coverageVersion!);v.statement={id:statementId,profile:'m75-synthetic-roster-statement-v1',input:v.activity.rosterStatement!,locator:`m75-roster-statement:${statementId}:declared-fleet`,text,sha256:qaHash(text),byteLength:Buffer.byteLength(text)};if(!Object.hasOwn(v,'qaKeepFindings'))v.findings=deriveM75RosterFindings(v.activity,register.proof.coverageVersion!);delete (v as any).qaKeepFindings;v.inputSha256=hash(m75InputPayload(v));v.contentSha256=hash(m75ContentPayload(v));v.versionSha256=hash(m75VersionHashPayload(v));const request={...v.activity,expectedDependencySha256:v.dependencies.dependencySha256,expectedVersionId:prior.id,expectedVersionSha256:prior.versionSha256,correctionReason:v.correctionReason,idempotencyKey:crypto.randomUUID()};return [seed.companyId,seed.rosterId,JSON.stringify(request),JSON.stringify(v),JSON.stringify(v.statement)]}
 const saveSql='select neuvetra.save_controlled_fleet($1,$2,$3::text::jsonb,$4::text::jsonb,$5::text::jsonb)'
 await probe('save_valid_control',true,saveSql,save())
 for(const id of ['unsupported_hidden','wrong_blocker','roster_null_confirmation','flags_null','missing_prior_row','duplicate_alias_hidden','capacity_26','string_model_year','lowercase_asset','numeric_asset','unknown_mode_enum','empty_discovery','extra_roster_key','string_all_trips','string_synthetic_flag','null_created_by','null_payload_company','null_payload_roster','null_payload_version'] as const){await probe(id,false,saveSql,save((a:any,v:any)=>{
  if(id==='unsupported_hidden'){a.rosterStatement.assets[0].modelYear=2024;v.findings=[];v.qaKeepFindings=true}
  if(id==='wrong_blocker'){a.rosterStatement.assets[0].modelYear=2024;v.findings=[{code:'roster_unconfirmed',rowKey:null,message:'Invented different finding',blocking:true}];v.qaKeepFindings=true}
  if(id==='roster_null_confirmation')a.manualConfirmation=null
  if(id==='flags_null')v.synthetic=null
  if(id==='string_synthetic_flag')v.synthetic='true'
  if(id==='null_created_by')v.createdBy=null
  if(id==='null_payload_company')v.companyId=null
  if(id==='null_payload_roster')v.rosterId=null
  if(id==='null_payload_version')v.version=null
  if(id==='string_model_year')a.rosterStatement.assets[0].modelYear='2018'
  if(id==='lowercase_asset')a.rosterStatement.assets[0].assetId='recovery-truck-a'
  if(id==='numeric_asset')a.rosterStatement.assets[0].assetId=123
  if(id==='unknown_mode_enum')a.rosterStatement.assets[0].mode='arbitrary_mode'
