test.skipIf(process.env.M75_INDEPENDENT_NATIVE!=='enabled')('M75 independent native lifecycle, access and stale historical evidence',async()=>{
 const name=`m75_qa_review_${Date.now()}`,admin=connect('postgres'),authority=createM74Authority();let op:ReturnType<typeof connect>|undefined,runtime:ReturnType<typeof connect>|undefined
 const events:string[]=[]
 try{
  console.log('Native QA connecting for new isolated clone '+name)
  expect((await admin.query('select datname from pg_database where datname=$1',[name])).rows.length).toBe(0)
  console.log('Native QA creating clone');await admin.exec(`create database ${name} template ${source}`);op=connect(name)
  const manifest=await readMigrationManifest(),receipts=(await op.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows
  expect(receipts.every((r,i)=>r.name===manifest[i]?.name&&r.sha256===manifest[i]?.sha256)).toBe(true)
  await op.transaction(async tx=>{for(const m of manifest.slice(receipts.length)){await tx.exec(m.sql);await tx.query('insert into neuvetra.schema_migrations(name,sha256) values($1,$2)',[m.name,m.sha256])}})
  const seeded=await populateM75RecoveryFixture(op,name,55463),company=seeded.companyId,owner=seeded.users.owner,fleetReviewer=seeded.users.fleetReviewer
  runtime=connect(name,'neuvetra_runtime');console.log('Native QA clone ready')
  const ref=(await op.query<{project_ref:string}>('select project_ref from neuvetra.staging_target')).rows[0]!.project_ref
  const db=new(HostedWorkspaceDatabase as any)(runtime,ref) as HostedWorkspaceDatabase
  const original=(await db.findControlledFleet(owner,company,authority))!;expect(original.reconciliation.status).toBe('reconciled_bounded_synthetic');await decodeFleetRegister(original,company);events.push('native positive register and real browser decoder')
  const reportMeta=original.reports[0]!,report=(await db.findControlledFleetReport(owner,company,original.rosterId!,reportMeta.id,authority))!,proof=(await db.findControlledFleetReportProof(owner,company,original.rosterId!,reportMeta.id,authority))!
  expect(proof.reportId).toBe(report.id);expect(proof.proof.coverageVersion?.id).toBe(original.proof.coverageVersion?.id)
  await Bun.write('evaluations/research-qa/m75-independent-ui-fixture.json',JSON.stringify({register:original,report,proof,owner,fleetReviewer},null,2)+'\n')
  await mustReject(db.findControlledFleet(qaId(900),company,authority),'Private staging access required.');await mustReject(db.findControlledFleetReport(qaId(900),company,original.rosterId!,reportMeta.id,authority),'Private staging access required.');events.push('foreign unprovisioned actor denied register/report')
  await mustReject(runtime.query('update neuvetra.controlled_fleet_versions set content_sha256=$1 where company_id=$2',['0'.repeat(64),company]));events.push('runtime direct DML refused')
  const v=original.versions.at(-1)!,base={...structuredClone(v.activity),expectedDependencySha256:original.reconciliation.dependencySha256,expectedVersionId:v.id,expectedVersionSha256:v.versionSha256,correctionReason:'Independent correction',idempotencyKey:crypto.randomUUID()}
  const foreign=crypto.randomUUID();await op.query('insert into auth.users(id) values($1)',[foreign]);await provisionStagingRoster(op,{expectedProjectRef:ref,workspaceId:crypto.randomUUID(),ownerUserId:foreign,members:[]})
  expect(await db.findControlledFleet(foreign,company,authority)).toBeNull();expect(await db.findControlledFleetReport(foreign,company,original.rosterId!,report.id,authority)).toBeNull()
  const member=crypto.randomUUID();await op.query('insert into auth.users(id) values($1)',[member]);await op.query("insert into neuvetra.company_members(company_id,user_id,role) values($1,$2,'member')",[company,member]);await op.query('insert into neuvetra.staging_access(user_id,company_id,active) values($1,$2,true)',[member,company])
  expect((await db.findControlledFleet(member,company,authority))!.headVersionId).toBe(original.headVersionId)
  const memberSave=structuredClone(base);memberSave.rosterStatement!.reference+='-MEMBER';await mustReject(db.saveControlledFleet(member,company,original.rosterId,memberSave,authority));await mustReject(db.createControlledFleetReport(member,company,original.rosterId!,{expectedReconciliationSha256:original.reconciliation.contentSha256,idempotencyKey:crypto.randomUUID()},authority))
  const origin='http://127.0.0.1:37579',actors:Record<string,string>={owner,member,foreign},route=createM75Routes({database:db,authority,origin,validateUser:async token=>actors[token]?{id:actors[token]!,email:null,phone:null,fullName:null}:null})
  const http=(suffix='',token:string|null='owner',method='GET',body?:string,requestOrigin=origin)=>route(new Request(`${origin}/workspace/${company}/controlled-fleet${suffix}`,{method,headers:{origin:requestOrigin,...(token?{authorization:'Bearer '+token}:{})},...(body===undefined?{}:{body})}))
  expect((await http('',null)).status).toBe(401);expect((await http('','unknown')).status).toBe(401);expect((await http('','owner','GET',undefined,'https://unrelated.invalid')).status).toBe(403);expect((await http('','foreign')).status).toBe(404)
